// Score each discovered item
const items = $input.all();
const scored = [];

for (const item of items) {
  const data = item.json;

  // Calculate scores
  const freshness = calculateFreshness(data.date);
  const replicability = analyzeReplicability(data.content);
  const impact = estimateImpact(data.content);
  const gap = checkContentGap(data.title);

  const totalScore = freshness + replicability + impact + gap;

  if (totalScore >= 70) {
    scored.push({
      json: {
        ...data,
        scores: { freshness, replicability, impact, gap, total: totalScore },
        briefId: generateBriefId(),
        timestamp: new Date().toISOString()
      }
    });
  }
}

return scored;

